import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

const Header = () => {
  const [showLogin, setShowLogin] = useState(false);
  const [showSignup, setShowSignup] = useState(false);
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [signupData, setSignupData] = useState({ username: '', name: '', email: '', role: 'freelancer', password: '' });
  const [error, setError] = useState('');

  const API_URL = 'http://localhost:5000/api'; // Adjust this when deploying

  const handleLoginChange = (e) => {
    setLoginData({ ...loginData, [e.target.id]: e.target.value });
  };

  const handleSignupChange = (e) => {
    setSignupData({ ...signupData, [e.target.id]: e.target.value });
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const response = await axios.post(`${API_URL}/login`, {
        email: loginData.email.trim(),
        password: loginData.password.trim(),
      });
      localStorage.setItem('token', response.data.token);
      setShowLogin(false);
      window.location.reload();
    } catch (error) {
      setError(error.response?.data?.error || 'Login failed. Please try again.');
    }
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      await axios.post(`${API_URL}/register`, {
        username: signupData.username.trim(),
        name: signupData.name.trim(),
        email: signupData.email.trim(),
        role: signupData.role.trim(),
        password: signupData.password.trim(),
      });
      setShowSignup(false);
      setShowLogin(true);
    } catch (error) {
      setError(error.response?.data?.error || 'Signup failed. Please try again.');
    }
  };

  return (
    <div className="header">
      <img src="/images/image1.png" alt="Logo" className="logo" />
      <div className="auth-buttons">
        <button className="custom-button" onClick={() => setShowLogin(true)}>Login</button>
        <button className="custom-button" onClick={() => setShowSignup(true)}>Sign Up</button>
      </div>

      {showLogin && (
        <div className="popup-overlay">
          <div className="form-container">
            <h2 className="title">Login</h2>
            {error && <p className="error-message">{error}</p>}
            <form className="form" onSubmit={handleLoginSubmit}>
              <div className="input-group">
                <label htmlFor="email">Email</label>
                <input type="email" id="email" value={loginData.email} onChange={handleLoginChange} required />
              </div>
              <div className="input-group">
                <label htmlFor="password">Password</label>
                <input type="password" id="password" value={loginData.password} onChange={handleLoginChange} required />
              </div>
              <button type="submit" className="sign">Sign In</button>
            </form>
            <button className="close-button" onClick={() => setShowLogin(false)}>&times;</button>
          </div>
        </div>
      )}

      {showSignup && (
        <div className="popup-overlay">
          <div className="form-container">
            <h2 className="title">Sign Up</h2>
            {error && <p className="error-message">{error}</p>}
            <form className="form" onSubmit={handleSignupSubmit}>
              <div className="input-group">
                <label htmlFor="username">Username</label>
                <input type="text" id="username" value={signupData.username} onChange={handleSignupChange} required />
              </div>
              <div className="input-group">
                <label htmlFor="name">Name</label>
                <input type="text" id="name" value={signupData.name} onChange={handleSignupChange} required />
              </div>
              <div className="input-group">
                <label htmlFor="email">Email</label>
                <input type="email" id="email" value={signupData.email} onChange={handleSignupChange} required />
              </div>
              <div className="input-group">
                <label htmlFor="role">Role</label>
                <select id="role" value={signupData.role} onChange={handleSignupChange} required>
                  <option value="freelancer">Freelancer</option>
                  <option value="client">Client</option>
                </select>
              </div>
              <div className="input-group">
                <label htmlFor="password">Password</label>
                <input type="password" id="password" value={signupData.password} onChange={handleSignupChange} required />
              </div>
              <button type="submit" className="sign">Sign Up</button>
            </form>
            <button className="close-button" onClick={() => setShowSignup(false)}>&times;</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Header;
